<script setup>
import { ShoppingBag, Search, Plus, Leaf, ChevronDown, Copy, X } from 'lucide-vue-next'
import { enquiryBasket, enquiryText } from '../../utils/marketplace-cart.js'
import { isUploadedPhoto, storefrontProducts, storefrontHeroImage } from '../../utils/storefront.js'
import { setResponseStatus } from 'h3'
const route = useRoute()
const slug = computed(() => String(route.params.farmSlug || ''))
const { data, error, status, refresh } = await useFetch(() => `/api/storefront/${encodeURIComponent(slug.value)}`, { watch: [slug] })
useHead(() => ({ title: data.value?.farm?.name ? `${data.value.farm.name} | Farm products` : 'Farm storefront', meta: [{ name: 'referrer', content: 'no-referrer' }] }))
const imagesEnabled = ref(false)
const failedImages = ref(new Set())
const search = ref('')
const sort = ref('name')
const availableOnly = ref(false)
const enquiryOpen = ref(false)
const products = computed(() => data.value?.products || [])
const visibleProducts = computed(() => storefrontProducts(products.value, search.value, sort.value, availableOnly.value))
const hasExternalImages = computed(() => [...products.value.map(product => product.imageUrl), data.value?.farm?.coverImageUrl].some(url => url && !isUploadedPhoto(url)))
const multipleCurrencies = computed(() => new Set(products.value.map(product => product.currency)).size > 1)
const monogram = computed(() => (data.value?.farm?.name || 'Farm').split(/\s+/).filter(Boolean).slice(0, 2).map(word => word[0]).join('').toUpperCase())
const theme = computed(() => ['green', 'teal', 'sage'].includes(data.value?.farm?.theme) ? data.value.farm.theme : 'green')
const canShowImage = product => Boolean(product.imageUrl && !failedImages.value.has(product.imageUrl) && (isUploadedPhoto(product.imageUrl) || imagesEnabled.value))
const heroProduct = computed(() => products.value.find(canShowImage))
const heroImage = computed(() => storefrontHeroImage(data.value?.farm, heroProduct.value, canShowImage))
function imageFailed(url) { failedImages.value = new Set([...failedImages.value, url]) }
const quantities = reactive({})
const basket = computed(() => enquiryBasket(products.value, quantities))
const selectedProducts = computed(() => {
  const selectedIds = new Set(Object.keys(quantities))
  return products.value.filter(item => selectedIds.has(item.id))
})
const orderText = computed(() => enquiryText(data.value?.farm || {}, basket.value))
const basketFeedback = ref('')
function add(product) {
  if (product.quantity <= 0) return
  const previous = Number(quantities[product.id])
  quantities[product.id] = Math.min(product.quantity, (Number.isFinite(previous) && previous > 0 ? previous : 0) + 1)
  enquiryOpen.value = true
  basketFeedback.value = `${product.name} added to your enquiry. No order has been placed.`
}
async function copyOrder() {
  if (!orderText.value) return
  try { await navigator.clipboard.writeText(orderText.value); basketFeedback.value = 'Enquiry copied. Share it with the farm contact below. Nothing has been sent by FarmBuddy.' }
  catch { basketFeedback.value = 'Copying was unavailable. Select and copy the enquiry text below, then share it with the farm contact.' }
}
watch(slug, () => {
  imagesEnabled.value = false
  failedImages.value = new Set()
  search.value = ''
  sort.value = 'name'
  availableOnly.value = false
  enquiryOpen.value = false
  for (const key of Object.keys(quantities)) delete quantities[key]
  basketFeedback.value = ''
})
if (import.meta.server && error.value) setResponseStatus(useRequestEvent(), error.value.statusCode === 404 || error.value.statusCode === 400 ? 404 : 503)
</script>

<template>
  <main class="storefront" :class="`theme-${theme}`">
    <a class="skip-link" href="#products">Skip to products</a>
    <div v-if="status === 'pending'" class="state-panel" role="status"><NuxtLink to="/">FarmBuddy</NuxtLink><h1>Loading farm products…</h1></div>
    <section v-else-if="error || !data" class="state-panel"><NuxtLink to="/">FarmBuddy</NuxtLink><h1>Storefront unavailable</h1><p>This farm may be unpublished or the link may have changed.</p><button type="button" @click="refresh">Try again</button></section>
    <template v-else>
      <header class="site-header wrap">
        <div class="farm-brand"><span class="monogram">{{ monogram }}</span><div><h1>{{ data.farm.name }}</h1><NuxtLink class="attribution" to="/"><Leaf :size="13" aria-hidden="true" /> FarmBuddy</NuxtLink></div></div>
        <a class="basket-link" href="#enquiry" @click="enquiryOpen = true"><ShoppingBag :size="18" aria-hidden="true" /><span>Enquiry</span><span class="count">{{ selectedProducts.length }}</span></a>
      </header>

      <section v-if="data.farm.showHero !== false" class="hero wrap" :class="{ 'has-photo': heroImage }" :aria-label="`${data.farm.name} storefront`">
        <img v-if="heroImage" :src="heroImage.url" :alt="heroImage.alt" fetchpriority="high" referrerpolicy="no-referrer" @error="imageFailed($event.currentTarget.getAttribute('src'))">
        <svg v-else class="field-art" viewBox="0 0 1200 300" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><rect width="1200" height="300" fill="#e4eee6"/><circle cx="1000" cy="68" r="38" fill="#d7e77f"/><path d="M400 300Q700 30 1200 160V300Z" fill="#bfd5bf"/><path d="M300 300Q800 100 1200 260V300Z" fill="#96b79a"/><path d="M720 300Q860 230 1200 285M890 300Q970 275 1200 315" fill="none" stroke="#dce8cd" stroke-width="12"/><path d="M1030 260V150M1030 203Q970 198 979 159Q1029 157 1030 203M1030 177Q1081 175 1087 125Q1037 125 1030 177" fill="none" stroke="#5a8767" stroke-width="5"/></svg>
        <div class="hero-copy"><h2>{{ data.farm.headline || data.farm.name }}</h2><p v-if="data.farm.tagline" class="tagline">{{ data.farm.tagline }}</p></div>
      </section>

      <section id="products" class="catalog wrap" aria-labelledby="products-title">
        <div class="section-heading"><h2 id="products-title">Products <span>{{ products.length }}</span></h2><span class="result-count" role="status">{{ visibleProducts.length }} showing<span v-if="multipleCurrencies && sort !== 'name'"> · Grouped by currency</span></span></div>
        <div class="toolbar">
          <label class="search-label" for="product-search"><Search :size="18" aria-hidden="true" /><span class="sr-only">Search products</span><input id="product-search" v-model="search" type="search" placeholder="Search products"></label>
          <label class="sort-label" for="product-sort"><span class="sr-only">Sort products</span><select id="product-sort" v-model="sort"><option value="name">Product name</option><option value="price-asc">{{ multipleCurrencies ? 'Currency, then price: low to high' : 'Price: low to high' }}</option><option value="price-desc">{{ multipleCurrencies ? 'Currency, then price: high to low' : 'Price: high to low' }}</option></select></label>
          <label class="available-filter"><input v-model="availableOnly" type="checkbox"> In stock only</label>
        </div>
        <label v-if="hasExternalImages" class="image-choice"><input v-model="imagesEnabled" type="checkbox"> Load external photos, including the cover (shares your IP address with image hosts).</label>
        <div v-if="visibleProducts.length" class="products">
          <article v-for="product in visibleProducts" :key="product.id" class="product-card">
            <div class="product-media"><img v-if="canShowImage(product)" :src="product.imageUrl" :alt="product.name" loading="lazy" referrerpolicy="no-referrer" @error="imageFailed($event.currentTarget.getAttribute('src'))"><div v-else class="photo-placeholder"><Leaf :size="48" :stroke-width="1.2" aria-hidden="true" /><span>{{ product.imageUrl && !isUploadedPhoto(product.imageUrl) && !imagesEnabled ? 'External photo paused' : 'Photo unavailable' }}</span></div><span class="stock-badge" :class="{ unavailable: product.quantity <= 0 }">{{ product.quantity > 0 ? 'In stock' : 'Out of stock' }}</span></div>
            <div class="product-body"><h3>{{ product.name }}</h3><p class="availability">{{ product.quantity > 0 ? `${product.quantity} ${product.unit} available` : 'Currently unavailable' }}</p><div class="product-bottom"><p class="price">{{ product.currency }} {{ product.price.toFixed(2) }}<span>/ {{ product.unit }}</span></p><button type="button" :disabled="product.quantity <= 0" :aria-label="`Add ${product.name} to enquiry`" @click="add(product)"><Plus :size="16" aria-hidden="true" /> Add</button></div><details v-if="product.description" class="product-details"><summary>Details <ChevronDown :size="13" aria-hidden="true" /></summary><p>{{ product.description }}</p></details></div>
          </article>
        </div>
        <div v-else class="empty"><h3>{{ products.length ? 'No matching products' : 'No products available yet' }}</h3><p>{{ products.length ? 'Try a different search or stock filter.' : 'Please check back soon.' }}</p><button v-if="products.length" type="button" @click="search = ''; availableOnly = false">Clear filters</button></div>
      </section>

      <div class="wrap enquiry-wrap">
        <p class="basket-feedback" role="status" aria-live="polite">{{ basketFeedback }}</p>
        <details id="enquiry" class="basket" :open="enquiryOpen" @toggle="enquiryOpen = $event.target.open">
          <summary><span><ShoppingBag :size="19" aria-hidden="true" /> Your enquiry <span class="count">{{ selectedProducts.length }}</span></span><ChevronDown :size="19" aria-hidden="true" /></summary>
          <div class="basket-content"><p v-if="!selectedProducts.length" class="basket-empty">Add products to start an enquiry.</p><template v-else><div v-for="product in selectedProducts" :key="product.id" class="basket-row"><label :for="`quantity-${product.id}`"><strong>{{ product.name }}</strong><span>{{ product.unit }} · up to {{ product.quantity }}</span></label><input :id="`quantity-${product.id}`" v-model.number="quantities[product.id]" type="number" min="0.001" :max="product.quantity" step="any" inputmode="decimal"><button class="remove-button" type="button" :aria-label="`Remove ${product.name} from enquiry`" @click="delete quantities[product.id]"><X :size="16" aria-hidden="true" /><span class="sr-only">Remove</span></button></div><p v-if="basket.invalid.length" class="validation" role="alert">Enter a valid positive quantity within available stock. Very large totals cannot be quoted.</p><template v-else><div class="totals"><p v-for="(cents, currency) in basket.totals" :key="currency"><span>Estimated total · {{ currency }}</span><strong>{{ currency }} {{ (cents / 100).toFixed(2) }}</strong></p></div><button class="copy-button" type="button" :disabled="!orderText" @click="copyOrder"><Copy :size="16" aria-hidden="true" /> Copy enquiry summary</button><label class="summary-label" for="enquiry-summary">Enquiry summary · nothing has been sent</label><textarea id="enquiry-summary" :value="orderText" readonly rows="6" /></template></template></div>
        </details>
      </div>
      <footer class="wrap"><details id="contact" class="contact"><summary>Contact {{ data.farm.name }} <ChevronDown :size="16" aria-hidden="true" /></summary><p v-if="data.farm.contact" class="contact-text">{{ data.farm.contact }}</p><p v-else>No public contact details shared yet.</p></details><p class="safety-note">Enquiries only. No orders, payments or stock reservations. Confirm details with the farm and verify the seller before paying.</p><NuxtLink class="footer-brand" to="/"><Leaf :size="16" aria-hidden="true" /> FarmBuddy</NuxtLink></footer>
    </template>
  </main>
</template>

<style scoped>
