:80px 24px}.state-panel h1{margin:30px 0 20px;font-size:28px}.state-panel p{line-height:1.7}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
@media(min-width:1400px){.products{grid-template-columns:repeat(4,minmax(0,1fr))}}@media(max-width:900px){.wrap{width:calc(100% - 40px)}.products{gap:16px}.product-body{padding:16px}.product-bottom{align-items:flex-start;flex-wrap:wrap}.toolbar{flex-wrap:wrap}.search-label{flex-basis:45%}.sort-label select{max-width:240px}.hero-copy{max-width:80%}}@media(max-width:640px){.wrap{width:calc(100% - 28px)}.site-header{padding-block:17px;gap:10px}h1{font-size:15px}.monogram{width:38px;height:38px;border-radius:14px;font-size:11px}.farm-brand{gap:8px}.basket-link{padding:10px 12px;gap:5px;font-size:11px}.basket-link>svg{width:15px}.hero{min-height:220px;height:auto;border-radius:22px}.hero-copy{padding:24px;max-width:95%}.hero h2{font-size:27px}.headline{font-size:16px}.tagline{font-size:12px}.catalog{padding-block:23px}.section-heading{margin-bottom:13px}.section-heading h2{font-size:19px}.result-count{font-size:10px}.toolbar{gap:10px;margin-bottom:17px}.search-label{flex-basis:100%}.sort-label{flex:1;min-width:0}.sort-label select{width:100%;max-width:100%;padding-inline:12px;font-size:10px}.available-filter{font-size:10px}.products{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.product-card{border-radius:20px}.product-media{aspect-ratio:1.1}.product-body{padding:13px 12px}.product-body h3{font-size:13px}.availability{font-size:9px;margin-bottom:12px}.price{font-size:13px}.price>span{font-size:9px}.product-bottom{gap:10px}.product-bottom button{padding:8px 11px;min-height:36px;font-size:10px}.stock-badge{top:9px;left:9px;font-size:9px;padding:5px 8px}.photo-placeholder{gap:8px}.photo-placeholder svg{width:34px}.photo-placeholder span{font-size:8px;text-align:center;padding-inline:8px}.product-details{margin-top:11px}.basket>summary{padding:18px;font-size:13px}.basket-content{padding:0 17px 18px}.basket-row{gap:8px}.basket-row input{width:67px}.basket-row label{font-size:11px}.basket-row label span{font-size:9px}.image-choice{font-size:10px}.enquiry-wrap{margin-top:4px}}@media(prefers-reduced-motion:reduce){.storefront *{transition:none!important;animation:none!important;scroll-behavior:auto!important}}
</style>
